// Runtime-aware Supabase client.
//
// Prefers values from window.__APP_CONFIG__ (served by /config.js), falling
// back to the Lovable-managed Vite env vars used by the auto-generated
// src/integrations/supabase/client.ts.
//
// This lets the same build run against:
//  - Lovable Cloud (preview) via VITE_SUPABASE_* env vars, and
//  - the self-hosted Supabase stack on Dokploy by swapping /config.js.
//
// IMPORTANT: do NOT edit src/integrations/supabase/client.ts — it is
// auto-generated by Lovable Cloud. Import this module instead:
//   import { supabase } from "@/integrations/supabase/clientRuntime";

import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";

declare global {
  interface Window {
    __APP_CONFIG__?: {
      SUPABASE_URL?: string;
      SUPABASE_ANON_KEY?: string;
    };
  }
}

const runtime =
  (typeof window !== "undefined" && window.__APP_CONFIG__) || {};

const SUPABASE_URL =
  (runtime.SUPABASE_URL && runtime.SUPABASE_URL.trim()) ||
  (import.meta.env.VITE_SUPABASE_URL as string);

const SUPABASE_ANON_KEY =
  (runtime.SUPABASE_ANON_KEY && runtime.SUPABASE_ANON_KEY.trim()) ||
  (import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string);

if (typeof window !== "undefined") {
  // Helpful breadcrumb when debugging which backend the app is talking to.
  // eslint-disable-next-line no-console
  console.info("[supabase] using URL:", SUPABASE_URL);
}

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_ANON_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
  },
});
